def is_prime(n):
    """Checks if a number n is prime."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def is_perfect_cube(n):
    """Checks if n is a perfect cube and returns its cube root if it is."""
    if n < 0:
        return None
    # Calculate the approximate cube root
    root = round(n**(1/3))
    # Check if the cube of the rounded root equals n
    if root**3 == n:
        return root
    return None

def solve_task():
    successful_pairs = []
    print("Starting test for primes q from 2 to 100...")

    for q in range(2, 101):
        if is_prime(q):
            # N = (q^3 + 1) / (q + 1) = q^2 - q + 1
            N = q*q - q + 1

            # Check if N is a perfect cube
            p = is_perfect_cube(N)

            if p is not None:
                # p is the potential cube root

                # Check if p is prime and p != q
                if is_prime(p) and p != q:
                    successful_pairs.append((q, p))
                    print(f"Found a pair: q={q}, N={N}, p={p}")

    return successful_pairs

pairs = solve_task()
